/// <summary>
/// This is a controller class for the Process invoice matching claims batch job.
/// </summary>
class METAutoInvoiceMatchingClaimsProcessController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Batch job caption.
/// </summary>
/// <returns>Caption.</returns>
public ClassDescription caption()
{
    return "@MET:ProcessInvoiceMatchClaims";
}

/// <summary>
/// Initiate the memory of the class.
/// </summary>
void new()
{
    super();

    this.parmClassName(classStr(METAutoInvoiceMatchingClaimsProcessService));
    this.parmMethodName(methodStr(METAutoInvoiceMatchingClaimsProcessService, processOperation));
}

/// <summary>
/// Starts the process flow.
/// </summary>
/// <param name = "args">args</param>
public static void main(Args args)
{
    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        METAutoInvoiceMatchingClaimsProcessController operation;

        operation = new METAutoInvoiceMatchingClaimsProcessController();

        operation.parmDialogCaption("@MET:ProcessInvoiceMatchClaims");
        operation.startOperation();
    }
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
